Translate("frFR", "un-goro-crater", {
	title = "Cratère d'Un'Goro",
	aliases = { "Un'Goro", "le Cratère" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le Cratère d'Un'Goro est une vaste cuvette verdoyante enfoncée dans le sud de {link:kalimdor}Kalimdor{/link}, ceinte de falaises entre les sables de {link:tanaris}Tanaris{/link} et les terres désolées de {link:silithus}Silithus{/link}. Sous son rebord, le monde semble appartenir à un autre âge. De la vapeur monte de ses sources, un volcan fume en son cœur, et la jungle est gouvernée par des bêtes que le reste du monde a depuis longtemps oubliées : des diablosaures tonitruants, des stégodons, des ptérodax ailés et des meutes de ravasaures. D'étranges cristaux scintillent dans l'herbe, et de hauts {link:crystal-pylons}pylônes de cristal{/link} se dressent à la lisière des terres sauvages.]=],
		},
		{
			title = "Origines",
			text = [=[Aucune chronique ne rapporte comment le cratère fut formé, ni quand. Les histoires du plus ancien des âges tiennent que les serviteurs des {red:titans}titans{/red} façonnèrent certaines terres du jeune monde en jardins de vie sauvage, et qu'Un'Goro était de celles-là. Les {link:crystal-pylons}pylônes de cristal{/link} qui se dressent autour de son rebord sont plus anciens que tout peuple vivant aujourd'hui en {link:kalimdor}Kalimdor{/link}, et aucun de ceux qui habitent le cratère ne sait qui les éleva ni pourquoi. Les {link:tauren}taurens{/link} qui viennent chasser ici sentent avec force la présence de la Terre-Mère dans la cuvette. À leurs yeux, ses créatures sont les parentes plus nobles des bêtes de leurs propres plaines.]=],
		},
		{
			title = "Le temps présent",
			text = [=[Le cratère a attiré depuis peu une foule de curieux et de naufragés. Une troupe d'explorateurs menée par {link:williden-marshal}Williden Marshal{/link} vint étudier la terre et faillit être anéantie par elle. Ses survivants tiennent un refuge rocheux sur les hauteurs du nord, où des gobelins de {link:gadgetzan}Gadgetzan{/link}, des érudits errants et des voyageurs égarés se sont rassemblés autour d'eux. Le {link:cenarion-circle}Cercle cénarien{/link} a fait demander la terre du cratère, qui renfermerait une magie puissante, et des druides de {link:darnassus}Darnassus{/link} et de {link:thunder-bluff}Thunder Bluff{/link} l'étudient. Au sud, les insectes de la ruche gorishi ont creusé la terre. Leur présence trouble les érudits, car rien de tel n'appartient à l'ordre naturel du cratère. De nos jours, les cartes nomment aussi la {red:shaper-s-terrace}Shaper's Terrace{/red} au sein du cratère, un lieu dont l'histoire est racontée sur sa propre page.]=],
		},
		{
			title = "Habitants",
			text = [=[• {b}Les grands sauriens.{/b} Les diablosaures chassent dans toute la cuvette. Les stégodons paissent au sud-ouest, les ravasaures courent en meutes au sud-est, et les diémétradons se chauffent le long de ses sentiers.
• {b}Les singes du {link:fungal-rock}Rocher fongique{/link}.{/b} De grands gorilles tiennent les grottes du nord-est et chassent quiconque approche.
• {b}Les Gorishi.{/b} Une ruche d'insectes a creusé la {link:the-slithering-scar}Balafre sinueuse{/link}, au sud.
• {b}Les élémentaires.{/b} Des êtres de flamme vivante arpentent les pentes du volcan, et des créatures de goudron surgissent des fosses du nord.
• {b}Pétales-de-sang et limons.{/b} Des plantes carnivores rampent dans les fourrés de l'est, et des limons s'amassent dans les marais.
• {b}Les nouveaux venus.{/b} Explorateurs, bricoleurs de {link:gadgetzan}Gadgetzan{/link} et vagabonds égarés se pressent au {link:marshal-s-refuge}Refuge des Marshal{/link}, et un chasseur {link:tauren}tauren{/link} tient son propre camp là où la route de {link:tanaris}Tanaris{/link} entre dans le cratère.]=],
		},
		{
			title = "Histoire",
			text = [=[• {b}L'âge des Façonneurs.{/b} Les pylônes et les cristaux du cratère datent d'un temps antérieur à tout royaume mortel. Aucune histoire mortelle ne rapporte leur érection.
• {b}L'expédition Marshal.{/b} La troupe de {link:williden-marshal}Williden Marshal{/link} installa des camps au sud-ouest et au nord-est du cratère. Les bêtes les submergèrent tous deux, et les survivants s'enfuirent au nord vers les hauteurs.
• {b}Le temps présent.{/b} Érudits, druides, chasseurs et au moins un vagabond qui ne se rappelle plus pourquoi il est venu cherchent désormais le cratère.]=],
		},
		{
			title = "Légendes du cratère",
			text = [=[• Au {link:marshal-s-refuge}Refuge des Marshal{/link}, on dit que les pylônes et les cristaux colorés de l'herbe vont ensemble, et que le bon mélange de couleurs éveillera leur pouvoir.
• {link:krakle}Krakle{/link} de {link:gadgetzan}Gadgetzan{/link} croit que les sources de {link:golakka-hot-springs}Golakka{/link} tirent leur chaleur du volcan, bien que ses calculs ne soient pas encore achevés.
• {link:torwa-pathfinder}Torwa Pathfinder{/link} avertit que {link:lar-korwi}Lar'korwi{/link}, le grand ravasaure de l'est, suivra des jours durant quiconque vole une part de sa proie.]=],
		},
	},
})

Translate("frFR", "marshal-s-refuge", {
	title = "Refuge des Marshal",
	sections = {
		{
			title = "Résumé",
			text = [=[Le Refuge des Marshal est un camp de tentes et de feux de cuisine installé parmi les rochers de la paroi nord du cratère. Il fut fondé dans la fuite. Quand les bêtes d'{link:un-goro-crater}Un'Goro{/link} submergèrent les camps des Expéditions Marshal, {link:williden-marshal}Williden Marshal{/link} et les siens grimpèrent sur ces hauteurs, où les grands sauriens ne pouvaient guère les suivre. D'autres les ont rejoints depuis : un maître de vol de {link:gadgetzan}Gadgetzan{/link}, des vagabonds égarés, des voyageurs querelleurs et une étudiante des cristaux qui travaille dans la grotte au-dessus du camp. Le refuge est le seul endroit du cratère où un voyageur peut dormir sans garder un œil ouvert.]=],
		},
	},
})

Translate("frFR", "fire-plume-ridge", {
	title = "Crête de la Fournaise",
	sections = {
		{
			title = "Résumé",
			text = [=[La Crête de la Fournaise est le volcan au centre d'{link:un-goro-crater}Un'Goro{/link}, un cône calciné qui déverse fumée et chaleur sur tout le cratère. Ses pentes appartiennent aux élémentaires de flamme vivante. En son cœur, sur des sentiers de roche noircie, demeure {link:blazerunner}Blazerunner{/link}, un élémentaire enveloppé d'une aura qu'aucune lame n'a percée. Il garde une grotte qui abrite la Flamme dorée. La chaleur de la crête est assez féroce pour terrasser les imprudents, et l'explorateur {link:ringo}Ringo{/link} faillit en mourir. Ceux qui étudient le cratère croient que le volcan pourrait réchauffer ses sources.]=],
		},
	},
})

Translate("frFR", "golakka-hot-springs", {
	title = "Sources de Golakka",
	aliases = { "Golakka" },
	sections = {
		{
			title = "Résumé",
			text = [=[Les Sources de Golakka fument dans la partie ouest du cratère, une chaîne de bassins chauds au milieu de la jungle. {link:krakle}Krakle{/link}, un érudit de {link:gadgetzan}Gadgetzan{/link}, a installé son camp à côté d'elles, loin de la sécurité du refuge. Il veut savoir d'où vient leur chaleur, et il soupçonne le volcan de la {link:fire-plume-ridge}Crête de la Fournaise{/link}, non loin à l'est. Ses mesures l'ont amené à s'interroger sur d'autres sources, dans le lointain {link:winterspring}Berceau-de-l'Hiver{/link}, où il n'y a aucun volcan.]=],
		},
	},
})

Translate("frFR", "lakkari-tar-pits", {
	title = "Fosses de goudron de Lakkari",
	aliases = { "Lakkari" },
	sections = {
		{
			title = "Résumé",
			text = [=[Les Fosses de goudron de Lakkari se trouvent au nord du cratère, au sud du {link:marshal-s-refuge}Refuge des Marshal{/link}. Ici, du goudron noir remonte du sol en larges mares collantes. Il en sort des créatures de goudron qui semblent vivre et se mouvoir de leur propre volonté. Les plus grandes, les seigneurs du goudron, rôdent près des mares du nord. De moindres bêtes et rampants de goudron errent plus au sud, vers les plaines au pied du volcan. Aucun registre ne dit qui donna leur nom aux fosses.]=],
		},
	},
})

Translate("frFR", "the-slithering-scar", {
	title = "La Balafre sinueuse",
	aliases = { "Balafre sinueuse" },
	sections = {
		{
			title = "Résumé",
			text = [=[La Balafre sinueuse est une grande déchirure dans le sol sud du cratère, où les insectes gorishi ont bâti leur ruche. Des guêpes emplissent l'air au-dessus, et ouvrières, ravageurs et fouisseurs rampent dans ses galeries. Dans des chambres profondes tapissées de larves, la ruche élève ses petits, et une reine les gouverne de l'intérieur. {link:hol-anyee-marshal}Hol'anyee Marshal{/link} étudiait les Gorishi quand son expédition s'enfuit. À ses yeux, ils n'appartiennent pas du tout au cratère.]=],
		},
	},
})

Translate("frFR", "terror-run", {
	title = "Coteaux de la terreur",
	sections = {
		{
			title = "Résumé",
			text = [=[Les Coteaux de la terreur sont la plaine sud-ouest du cratère, et ils ont mérité leur nom. Les stégodons y paissent en lourds troupeaux, et les diablosaures chassent parmi eux. Les Expéditions Marshal vinrent ici déterrer les os de bêtes mortes. Les fouilleurs découvrirent vite que les bêtes vivantes étaient bien plus nombreuses, et bien plus dangereuses. {link:spark-nilminer}Spark Nilminer{/link}, le chef des fouilles de l'expédition, parle encore de l'endroit avec une frayeur non dissimulée. Il l'appelle un piège mortel, et ce n'est pas une plaisanterie.]=],
		},
	},
})

Translate("frFR", "fungal-rock", {
	title = "Rocher fongique",
	sections = {
		{
			title = "Résumé",
			text = [=[Le Rocher fongique est un creux de grottes au nord-est du cratère, et c'est l'antre des grands singes d'{link:un-goro-crater}Un'Goro{/link}. Gorilles, écraseurs et tonneurs le défendent, et aucun n'est plus féroce que le puissant singe que le chasseur {link:tauren}tauren{/link} {link:torwa-pathfinder}Torwa{/link} appelle {link:u-cha}U'cha{/link}. L'inventrice {link:karna-remtravel}Karna Remtravel{/link} envoya son singe mécanique {link:a-me-01}A-Me 01{/link} dans ces grottes pour observer les singes de près. Les singes ne furent pas dupes longtemps. Quand des voyageurs la retrouvèrent, elle gisait muette et gravement cabossée à l'entrée des grottes.]=],
		},
	},
})

Translate("frFR", "the-marshlands", {
	title = "La Fondrière",
	aliases = { "Fondrière" },
	sections = {
		{
			title = "Résumé",
			text = [=[La Fondrière forme les basses terres humides de l'est du cratère, un pays de boue, de roseaux et d'eau dormante. Des limons de bien des sortes s'amassent dans ses mares, et des pétales-de-sang rampent dans ses fourrés. L'un des camps abandonnés de l'expédition se trouvait de ce côté du cratère, et ses réserves restèrent intactes dans la boue longtemps après la fuite des explorateurs. Un radeau naufragé repose près d'un petit étang plus au sud, loin de toute eau qui aurait pu l'y porter. Il appartenait au vagabond {link:linken}Linken{/link}, bien que celui-ci ne s'en souvînt plus.]=],
		},
	},
})

Translate("frFR", "crystal-pylons", {
	title = "Pylônes de cristal",
	aliases = { "pylônes de cristal", "les pylônes d'Un'Goro" },
	sections = {
		{
			title = "Résumé",
			text = [=[Trois pylônes de cristal se dressent dans les terres sauvages du {link:un-goro-crater}Cratère d'Un'Goro{/link} : un au nord, un contre la paroi est et un à l'ouest. Ce sont de hautes œuvres de pierre tapissées de cristal à l'intérieur, et elles sont bien plus anciennes que le camp de n'importe quel explorateur vivant. Longtemps, elles ne furent que des rumeurs colportées au {link:marshal-s-refuge}Refuge des Marshal{/link}.]=],
		},
		{
			title = "Les cristaux",
			text = [=[Des cristaux colorés sont éparpillés sur le sol du cratère : rouges, bleus, jaunes et verts. La plupart des voyageurs les ignorent. Pas la {link:gnomes}gnome{/link} {link:j-d-collie}J.D. Collie{/link}. Elle les ramassa par sacs entiers et essaya toutes les combinaisons qu'elle put imaginer, mais ils ne livrèrent rien avant que l'on trouve les pylônes. Une fois que des voyageurs eurent examiné les trois, elle étudia ce qu'ils avaient vu et consigna ses découvertes dans un manuel. Grâce à lui, on pouvait fondre les cristaux en combinaisons qui restaurent, renforcent, protègent et chargent ceux qui les portent.]=],
		},
		{
			title = "Sans réponse",
			text = [=[Qui éleva les pylônes, et dans quel but, le cratère ne le dit pas. {link:j-d-collie}J.D. Collie{/link} apprit à se servir de leurs cristaux. Elle n'apprit pas pourquoi ils étaient là.]=],
		},
	},
})

Translate("frFR", "williden-marshal", {
	title = "Williden Marshal",
	subtitle = "Chef des Expéditions Marshal",
	found = "Le Refuge des Marshal, parmi les tentes",
	hint = [=[Parlez au chef de l'expédition qui s'est réfugiée sur les hauteurs nord du cratère.]=],
	allegiance = "Expéditions Marshal",
	aliases = { "Williden" },
	sections = {
		{
			title = "Résumé",
			text = [=[Williden Marshal dirige les Expéditions Marshal, une troupe d'explorateurs qui ne répondent à aucune nation. Il les amena dans {link:un-goro-crater}le Cratère{/link} d'Un'Goro pour l'étudier, et le cratère faillit bien les tuer tous. Il maintient désormais en vie ce qui reste des siens sur les hauteurs rocheuses qui portent son nom.]=],
		},
		{
			title = "Importance",
			text = [=[Williden est la raison pour laquelle il existe un terrain sûr dans le cratère. Le refuge que ses gens bâtirent dans leur fuite est devenu le lieu de rassemblement de tous ceux qui viennent à {link:un-goro-crater}Un'Goro{/link}, par choix ou par malheur. Il ne prétend pas que l'expédition s'est bien passée. Il admet que sa troupe a bien trop sous-estimé la sauvagerie du cratère.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il mena l'expédition qui installa des camps au sud-ouest et au nord-est du cratère.
• Quand les bêtes submergèrent les deux camps, il mena les survivants au nord vers les hauteurs.
• Il demande aux voyageurs de récupérer les vivres et le matériel de recherche que ses gens ont abandonnés.
• Il tient un journal de l'expédition, qui fut perdu dans la fuite.]=],
		},
		{
			title = "Non consigné",
			text = [=[Aucun registre ne dit d'où venait Williden ni comment il fonda sa troupe. Cette entrée ne rapporte que ce que le cratère a fait de lui.]=],
		},
	},
	chapters = {
		{
			title = "Le salut de l'expédition",
			hint = "Récupérez ce que l'expédition a abandonné dans sa fuite.",
			text = [=[Les camps avaient été abandonnés à la hâte, et avec eux les vivres et les instruments de l'expédition. Sans les uns, les explorateurs mourraient de faim. Sans les autres, toutes leurs souffrances n'auraient servi à rien. Quand les uns et les autres furent rapportés au refuge, Williden déclara que l'expédition elle-même avait été sauvée, et il tint celui qui l'avait sauvée pour un ami de sa compagnie à vie.]=],
		},
		{
			title = "Le journal mutilé",
			hint = "Rendez un journal perdu à son propriétaire.",
			text = [=[Un journal déchiré et piétiné fut trouvé dans les terres sauvages. On pouvait encore en lire assez pour connaître l'histoire de l'expédition : les camps submergés, la fuite, la recherche de hauteurs au nord. Williden l'avait compté parmi les nombreuses choses que le cratère lui avait prises. Il fut heureux de le retrouver.]=],
		},
	},
	mentions = {
		{ text = "Le salut de l'expédition" },
		{ text = "Le journal de Williden" },
	},
	bonds = {
		{ id = "hol-anyee-marshal", name = "Hol'anyee Marshal", note = "partage son nom et son expédition" },
		{ id = "spark-nilminer", name = "Spark Nilminer", note = "son chef des fouilles" },
	},
})

Translate("frFR", "hol-anyee-marshal", {
	title = "Hol'anyee Marshal",
	subtitle = "Érudite des Expéditions Marshal",
	found = "Le Refuge des Marshal, à côté de Williden",
	hint = [=[Parlez à l'érudite de l'expédition, qui se tient à côté de son chef.]=],
	allegiance = "Expéditions Marshal",
	aliases = { "Hol'anyee" },
	sections = {
		{
			title = "Résumé",
			text = [=[Hol'anyee Marshal est une érudite des Expéditions Marshal. Avant que l'expédition ne s'enfuie au nord, elle étudiait les insectes gorishi du sud du cratère. La retraite n'a pas mis fin à son travail. Elle croit que les Gorishi sont étrangers à la vie du cratère, et elle entend apprendre comment ils en vinrent à s'y trouver.]=],
		},
		{
			title = "Importance",
			text = [=[Hol'anyee est la première à dire tout haut que la ruche gorishi n'a pas sa place à {link:un-goro-crater}Un'Goro{/link}.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Elle étudia les Gorishi du sud avant que les camps ne soient submergés.
• Elle envoya une fiole à racler dans la ruche pour prélever un échantillon des parois de ses couvoirs.]=],
		},
	},
	mentions = {
		{ text = "Écologie extraterrestre" },
	},
	bonds = {
		{ id = "williden-marshal", name = "Williden Marshal", note = "dirige l'expédition" },
	},
})

Translate("frFR", "spark-nilminer", {
	title = "Spark Nilminer",
	subtitle = "Chef des fouilles des Expéditions Marshal",
	found = "Le Refuge des Marshal",
	hint = [=[Trouvez le fouilleur de l'expédition, qui n'a plus guère d'amour pour les fouilles.]=],
	allegiance = "Expéditions Marshal",
	aliases = { "Spark" },
	sections = {
		{
			title = "Résumé",
			text = [=[Spark Nilminer est le chef des fouilles des Expéditions Marshal. Sa tâche était de déterrer les os de stégodons et de diémétradons morts dans les {link:terror-run}Coteaux de la terreur{/link}. Les bêtes vivantes rendirent ce travail presque impossible, et Spark en est venu à haïr l'endroit. {link:williden-marshal}Williden{/link} et {link:hol-anyee-marshal}Hol'anyee{/link} veulent toujours leurs os, et Spark préfère ne pas demander comment on les rassemble.]=],
		},
		{
			title = "Importance",
			text = [=[Spark parle pour les membres ordinaires de l'expédition, venus travailler et qui ne veulent plus que repartir vivants.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il fut envoyé déterrer des os dans les {link:terror-run}Coteaux de la terreur{/link}.
• Il prend des os de n'importe quelle provenance, et demande aux voyageurs de taire d'où ils viennent.]=],
		},
	},
	mentions = {
		{ text = "Rouler les os" },
	},
	bonds = {
		{ id = "williden-marshal", name = "Williden Marshal", note = "son chef" },
	},
})

Translate("frFR", "j-d-collie", {
	title = "J.D. Collie",
	subtitle = "Étudiante des cristaux",
	found = "La grotte au-dessus du Refuge des Marshal",
	hint = [=[Cherchez la gnome qui travaille avec des cristaux luisants dans la grotte au-dessus du refuge.]=],
	allegiance = "Refuge des Marshal",
	aliases = { "J.D." },
	sections = {
		{
			title = "Résumé",
			text = [=[J.D. Collie est une {link:gnomes}gnome{/link} qui a installé son atelier dans la grotte au-dessus du {link:marshal-s-refuge}Refuge des Marshal{/link}. Elle est fascinée par les cristaux colorés qui jonchent tout {link:un-goro-crater}Un'Goro{/link} et par les rumeurs de grands pylônes dans les terres sauvages. Elle croit presque toutes les histoires qu'elle entend, et dans le cratère cette confiance l'a étonnamment bien servie.]=],
		},
		{
			title = "Importance",
			text = [=[J.D. est la première à percer le sens des {link:crystal-pylons}pylônes de cristal{/link}. D'autres passèrent des années à côté des cristaux. Elle les ramassa, les éprouva et apprit enfin à lier leur pouvoir. Elle fut aussi bonne envers le vagabond {link:linken}Linken{/link} quand il arriva en titubant au refuge, et les quelques mots qu'il lui dit dans sa confusion furent la clé de sa mémoire.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Elle ramasse des cristaux de quatre couleurs et les éprouve en combinaisons sans fin.
• Elle envoie des voyageurs trouver les pylônes du nord, de l'est et de l'ouest.
• Elle écrivit un manuel des pylônes et des cristaux.
• Elle orienta la recherche du passé de {link:linken}Linken{/link} vers {link:eridan-bluewind}Eridan Bluewind{/link}, à {link:felwood}Gangrebois{/link}.]=],
		},
	},
	chapters = {
		{
			title = "Les trois pylônes",
			hint = "Trouvez les pylônes de cristal dont J.D. a entendu parler.",
			text = [=[Longtemps, les expériences de J.D. ne donnèrent rien, et elle commença à craindre que les cristaux n'aient aucun pouvoir. Puis des voyageurs trouvèrent les pylônes l'un après l'autre : un au nord, un contre la paroi est, un à l'ouest. Elle prit ce qu'ils avaient vu et l'étudia dans sa grotte. Quand elle eut fini, elle savait comment unir les cristaux, et elle consigna tout dans un livre.]=],
		},
		{
			title = "La mémoire d'une gnome",
			hint = [=[Demandez à la gnome des cristaux ce que le vagabond perdu lui a dit jadis.]=],
			text = [=[Quand {link:linken}Linken{/link} arriva au refuge, il était hébété et marmonnait d'étranges choses. J.D. se souvint d'une chose qu'il avait dite : qu'il fabriquait un totem, et qu'il devait trouver quelqu'un du nom d'{link:eridan-bluewind}Eridan Bluewind{/link} à {link:felwood}Gangrebois{/link}. C'était un mince fil, mais il mena jusqu'à {link:blazerunner}Blazerunner{/link}.]=],
