			text = [=[L'aide d'une {link:gnomes}gnome{/link}, envoyée par {link:linken}Linken{/link}]=],
		},
		{ text = "La mémoire de {link:linken}Linken{/link}" },
		{ text = "Aquementas, le totem qu'on lui apporta" },
		{ text = "L'aventure de {link:linken}Linken{/link}" },
	},
	bonds = {
		{ id = "linken", name = "Linken", note = "elle se souvint de ce qu'il avait oublié" },
