})

Translate("frFR", "linken", {
	title = "Linken",
	subtitle = "Le vagabond sans mémoire",
	found = "Le Refuge des Marshal",
	hint = [=[Parlez au vagabond du refuge qui ne se souvient pas comment il y est arrivé.]=],
	allegiance = "Aucune dont il se souvienne",
	sections = {
		{
			title = "Résumé",
			text = [=[Linken est un {link:gnomes}gnome{/link} arrivé dans {link:un-goro-crater}le Cratère{/link} d'Un'Goro sans aucun souvenir de qui il était ni de ce qui l'amenait. Il sait seulement que quelque chose d'important l'a conduit ici. Contrairement à la plupart des siens, il ne s'intéresse pas aux gadgets. {link:j-d-collie}J.D. Collie{/link} soupçonne qu'il est un guerrier dans l'âme.]=],
		},
		{
			title = "Importance",
			text = [=[La mission oubliée de Linken se révèle être l'un des grands exploits du cratère. Il était venu affronter {link:blazerunner}Blazerunner{/link}, l'élémentaire enveloppé de flammes de la {link:fire-plume-ridge}Crête de la Fournaise{/link}, et lui prendre un artefact d'une puissance terrible. Quand sa mémoire revient, il ne revendique pas l'exploit pour lui-même. Il le confie à celui qui l'a rétabli.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il vint à {link:un-goro-crater}Un'Goro{/link} au terme d'un long voyage dont la dernière étape était la défaite de {link:blazerunner}Blazerunner{/link}.
• Il chercha auprès d'{link:eridan-bluewind}Eridan Bluewind{/link}, de {link:felwood}Gangrebois{/link}, un totem assez puissant pour dissiper l'aura de Blazerunner.
• Il entend rapporter la Flamme dorée dans sa patrie, où elle ne pourra plus jamais servir le mal.]=],
		},
		{
			title = "Non consigné",
			text = [=[La patrie de Linken n'est pas nommée, et il n'a pas dit qui il était avant de perdre la mémoire.]=],
		},
	},
	chapters = {
		{
			title = "Le paquetage perdu",
			hint = "Rendez un paquetage perdu à son propriétaire, au refuge.",
			text = [=[Un radeau naufragé gisait près d'un petit étang, loin de toute eau qui aurait pu l'y porter. Au fond de l'étang se trouvait un paquetage détrempé : une boussole, une carte roulée et une clé en forme de tête de lion. Linken les regarda et quelque chose remua en lui. Il se souvint d'une épée qu'il devait renforcer, sans savoir pourquoi. Il l'envoya au nord à {link:donova-snowden}Donova Snowden{/link}, à {link:winterspring}Berceau-de-l'Hiver{/link}.]=],
		},
		{
			title = "L'épée trempée",
			hint = "Voyez l'épée de Linken achevée.",
			text = [=[L'épée passa de main en main. {link:donova-snowden}Donova{/link} la trempa dans ses sources chaudes. Un élixir de {link:gregan-brewspewer}Gregan Brewspewer{/link} de {link:feralas}Féralas{/link} permit à son porteur de marcher en esprit près de {link:gadgetzan}Gadgetzan{/link} et de parler au fantôme {red:gaeriyan}Gaeriyan{/red}. Sous une pierre tombale, l'épée fut changée dans un éclair de lumière. Linken la reprit en main et ne sut toujours pas dire à quoi elle servait.]=],
		},
		{
			title = "La Flamme dorée",
			hint = "Achevez ce que Linken était venu faire dans le cratère.",
			text = [=[Le totem d'Aquementas lui rendit enfin la mémoire. Linken sut alors qu'il était venu combattre {link:blazerunner}Blazerunner{/link}, qui gardait la Flamme dorée. Il sut aussi qu'il n'était plus celui qui devait le faire. Quand Blazerunner tomba et qu'on lui apporta la Flamme, il promit de la ramener chez lui et de la garder en sûreté.]=],
		},
	},
	mentions = {
		{ text = "C'est un secret pour tout le monde" },
		{ text = "C'est un secret pour tout le monde, le paquetage perdu" },
		{ text = "C'est un secret pour tout le monde, l'épée" },
		{ text = "L'élixir de Videre" },
		{ text = "Rendez-vous à la tombe" },
		{ text = "Une situation grave" },
		{ text = "L'épée de Linken" },
		{ text = "L'aide d'une {link:gnomes}gnome{/link}" },
		{ text = "Cœur d'argent" },
		{ text = "Aquementas" },
		{ text = "L'aventure de Linken" },
		{ text = "C'est dangereux d'y aller seul" },
	},
	bonds = {
		{ id = "j-d-collie", name = "J.D. Collie", note = "se souvint de ses paroles" },
		{ id = "blazerunner", name = "Blazerunner", note = "l'ennemi qu'il était venu affronter" },
		{ id = "donova-snowden", name = "Donova Snowden", note = "trempa son épée" },
		{ id = "eridan-bluewind", name = "Eridan Bluewind", note = "savait ce qu'il cherchait" },
	},
})

