	},
	mentions = {
		{ text = "Perdu !" },
		{ text = "Un petit coup de main de mes amis" },
	},
	bonds = {
		{ id = "spraggle-frock", name = "Spraggle Frock", note = "son ami" },
	},
})

Translate("frFR", "shizzle", {
