	},
	bonds = {
		{ id = "linken", name = "Linken", note = "vint l'affronter" },
	},
})

Translate("frFR", "king-mosh", {
	title = "Roi Mosh",
	subtitle = "Le grand diablosaure",
	found = "Errant dans l'ouest du cratère",
	hint = [=[Méfiez-vous du plus puissant des diablosaures, qui erre dans l'ouest du cratère.]=],
	allegiance = "Les bêtes du cratère",
	sections = {
		{
			title = "Résumé",
			text = [=[Le roi Mosh est le plus grand des diablosaures d'{link:un-goro-crater}Un'Goro{/link}. Il parcourt la moitié ouest du cratère, depuis les environs des {link:golakka-hot-springs}Sources de Golakka{/link} jusqu'aux falaises au pied du {link:marshal-s-refuge}Refuge des Marshal{/link}, au nord. Parmi des bêtes qui écrasent déjà de leur taille tout autre chasseur du pays, il se distingue, et le nom qu'il porte est celui d'un roi.]=],
		},
		{
			title = "Importance",
			text = [=[Les diablosaures sont la terreur du cratère, et Mosh est la terreur des diablosaures. Le souhait de {link:torwa-pathfinder}Torwa Pathfinder{/link} d'apaiser ces bêtes plutôt que de les tuer montre combien la force mortelle compte peu face à elles.]=],
		},
		{ title = "Hauts faits", text = "• Il chasse dans tout l'ouest du cratère." },
		{
			title = "Non consigné",
			text = [=[Aucun récit du refuge ne dit d'où vient son nom, ni qui le lui donna le premier.]=],
		},
	},
	bonds = {
		{ id = "torwa-pathfinder", name = "Torwa Pathfinder", note = "cherche à apaiser ses semblables" },
	},
})
